// ✏️  FILL IN THE VALUES BELOW, then click Save.
// Every other node in this workflow reads its settings from here.
return [{
  json: {
    // Your Netlify site + /api (no trailing slash)
    site_api_url: "https://intake-ops-ai.netlify.app/api",
    // Must match INTAKEOPS_API_KEY in Netlify exactly
    intakeops_api_key: "PASTE_YOUR_INTAKEOPS_API_KEY",
  },
}];

const req = $('Vapi Tool Call').first().json;
const body = req.body ?? req;
const msg = body.message ?? body;
const call = msg.call ?? body.call ?? {};
const toolCall =
  (msg.toolCallList ?? msg.toolCalls ?? [])[0] ??
  msg.toolWithToolCallList?.[0]?.toolCall ?? {};
// Function tools send Vapi's tool-call envelope; API Request tools POST the
// parameters as the whole body.
let args = toolCall.function?.arguments ?? toolCall.arguments ?? (body.message ? {} : body);
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { args = {}; }
}
const toolCallId = toolCall.id ?? '';

const industry = String(args.industry ?? '').toLowerCase();
return [{
  json: {
    tool_call_id: toolCallId,
    escalation: {
      caller_name: String(args.caller_name || 'Unknown caller'),
      caller_phone: String(args.caller_phone || call.customer?.number || msg.customer?.number || ''),
      service_address: String(args.service_address ?? ''),
      issue_description: String(args.issue_description || 'Emergency reported on a call'),
      industry: ['plumbing', 'legal', 'med-spa', 'property-management', 'general'].includes(industry) ? industry : 'general',
    },
  },
}];

const ok = $input.first().json.status === 'escalated';
const result = ok
  ? 'The on-call team has been notified by text and will call the caller back within 15 minutes.'
  : "The automatic page didn't go through. Tell the caller their emergency is logged as top priority " +
    'and a team member will call them back as soon as possible.';
return [{ json: { tool_call_id: $('Parse Tool Call').first().json.tool_call_id, result } }];
